using Clock=std::chrono::steady_clock;
static volatile std::uint64_t sink;
#define BARRIER() asm volatile("" ::: "memory")
template<class Tr>struct Owned { Tr trie; ~Owned(){
#ifdef NYAAN_ORIGINAL
 delete[] trie.pool;
#endif
}};
static unsigned key(std::size_t i){return unsigned(i*2654435761u)&((1u<<30)-1);}
template<std::size_t D,int Mode,bool IDs>void updates(){
 constexpr std::size_t Ops=Mode==1?32768:D;
 constexpr int Capacity=static_cast<int>(1+(Mode==2?122*D:Mode==1?31*D+60*Ops:61*D));
 constexpr int Rounds=Mode==1?1:D==1?2000:D==32?300:1;
 using Tr=BinaryTrie<unsigned,29,Capacity>;
 std::uint64_t add_ns=0,del_ns=0,total=0;
 for(int round=0;round<Rounds;++round){
  Owned<Tr> own;auto &tr=own.trie;
  if constexpr(Mode!=0)for(std::size_t i=0;i<D;++i)tr.add(key(i),IDs?5:-1);
  if constexpr(Mode==2)for(std::size_t i=0;i<D;++i)tr.del(key(i));
  BARRIER();auto start=Clock::now();
  for(std::size_t i=0;i<Ops;++i)tr.add(key(i%D),IDs?9:-1);
  add_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();
  total+=tr.find(key(0)).first;
  BARRIER();start=Clock::now();
  for(std::size_t i=0;i<Ops;++i)tr.del(key(i%D));
  del_ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();
  if(tr.find(key(0)).first!=(Mode==1?1:0))std::abort();
#ifdef NYAAN_ORIGINAL
  if(tr.pid>Capacity)std::abort();
#endif
 }
 sink=total;const char *mode=Mode==0?"new":Mode==1?"duplicate":"reuse";
 std::printf("D%zu/%s/%s/add,%.6f,%" PRIu64 ",%d\n",D,mode,IDs?"IDs":"anon",double(add_ns)/(Ops*Rounds),total,Capacity);
 std::printf("D%zu/%s/%s/del,%.6f,%" PRIu64 ",%d\n",D,mode,IDs?"IDs":"anon",double(del_ns)/(Ops*Rounds),total,Capacity);
}
template<std::size_t D>void allupdates(){updates<D,0,false>();updates<D,1,false>();updates<D,2,false>();updates<D,0,true>();updates<D,1,true>();updates<D,2,true>();}
template<int Op,class Tr,class T>[[gnu::noinline,gnu::aligned(64)]] std::uint64_t query(Tr&tr,const std::vector<T>&q,std::size_t n,std::size_t size){
 std::uint64_t r=0;
 for(std::size_t i=0;i<n;++i){BARRIER();const auto x=q[i&(q.size()-1)];
  if constexpr(Op==0)r+=tr.find(x).first;
  else if constexpr(Op==1)r+=static_cast<std::uint64_t>(tr.min_element().first);
  else if constexpr(Op==2)r+=static_cast<std::uint64_t>(tr.max_element().first);
  else if constexpr(Op==3)r+=static_cast<std::uint64_t>(tr.get_kth(1+static_cast<std::uint64_t>(x)%size).first);
  else {tr.operate_xor(x);r+=static_cast<std::uint64_t>(x);}
 }
 return r;
}
template<int Op=0,class Tr,class T>void allqueries(const std::string&name,Tr&tr,const std::vector<T>&q,std::vector<T>sorted){
 constexpr std::size_t Warm=4096,N=200000;
 sink=query<Op>(tr,q,Warm,sorted.size());
 if constexpr(Op==4)for(std::size_t i=0;i<Warm;++i)tr.operate_xor(q[i&(q.size()-1)]);
 auto start=Clock::now();auto sum=query<Op>(tr,q,N,sorted.size());
 auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();
 sink=sum;
 if constexpr(Op==4)for(std::size_t i=0;i<N;++i)tr.operate_xor(q[i&(q.size()-1)]);
 std::uint64_t expected=0;
 for(std::size_t i=0;i<N;++i){const auto x=q[i&(q.size()-1)];
  if constexpr(Op==0){auto [a,b]=std::equal_range(sorted.begin(),sorted.end(),x);expected+=std::size_t(b-a);}
  else if constexpr(Op==1)expected+=static_cast<std::uint64_t>(sorted.front());
  else if constexpr(Op==2)expected+=static_cast<std::uint64_t>(sorted.back());
  else if constexpr(Op==3)expected+=static_cast<std::uint64_t>(sorted[static_cast<std::uint64_t>(x)%sorted.size()]);
  else expected+=static_cast<std::uint64_t>(x);
 }
 if(sum!=expected || tr.find(sorted.front()).first!=std::count(sorted.begin(),sorted.end(),sorted.front()))std::abort();
 constexpr const char *names[]={"find","min","max","kth","xor"};
 std::printf("%s/%s,%.6f,%" PRIu64 ",%zu\n",name.c_str(),names[Op],double(ns)/N,sum,sorted.size());
 if constexpr(Op<4)allqueries<Op+1>(name,tr,q,std::move(sorted));
}
template<class T,int L,int Cap>void scenario(const std::string&name,std::vector<T>keys,std::uint64_t mask){
 Owned<BinaryTrie<T,L,Cap>> own;auto &tr=own.trie;for(auto x:keys)tr.add(x);
 std::mt19937_64 rng(9716);std::vector<T>q(4096);for(std::size_t i=0;i<q.size();++i)q[i]=i%2?keys[rng()%keys.size()]:static_cast<T>(rng()&mask);
 std::sort(keys.begin(),keys.end());allqueries(name,tr,q,std::move(keys));
}
int main(){std::puts("case,ns_per_op,checksum,capacity_or_distinct");
