 std::vector<std::int64_t>signedskew{0};for(int i=0;i<63;++i)signedskew.push_back(std::int64_t{1}<<i);scenario<std::int64_t,62,4097>("signed63",signedskew,(std::uint64_t{1}<<63)-1);
