#ifndef TRIE_SOURCE
#define TRIE_SOURCE "/home/reinsirk/Atcoder_Env/DataStructure/Binary_Trie.cpp"
#endif
#include TRIE_SOURCE
#include <chrono>
#include <cinttypes>
#include <cstdio>
#include <cstdlib>
#include <cstdint>

using Trie = BinaryTrie<std::uint32_t, 29>;
using Clock = std::chrono::steady_clock;
static volatile std::uint64_t sink;
static std::uint32_t key(std::size_t i) {
    return static_cast<std::uint32_t>(i * 2654435761u) & ((1u << 30) - 1);
}
static int id_for(std::size_t i, int ids) {
    return ids == 0 || (ids == 2 && (i & 1u) == 0) ? -1 : 9;
}
// 新規・既存・解放済みノードの再利用を独立して計測する。構築・削除は計測外。
static void run(std::size_t distinct, int ids, int mode) {
    const int rounds = mode == 1 ? 1 : distinct == 1 ? 2000 : distinct == 32 ? 300 : 1;
    const std::size_t operations = mode == 1 ? 200000 : distinct;
    std::uint64_t elapsed = 0, checksum = 0;
    for (int round = 0; round < rounds; ++round) {
        Trie trie;
        if (mode != 0) {
            for (std::size_t i = 0; i < distinct; ++i) trie.add(key(i), id_for(i, ids));
        }
        if (mode == 2) {
            for (std::size_t i = 0; i < distinct; ++i) {
                if (!trie.del(key(i), id_for(i, ids))) std::abort();
            }
        }
        constexpr std::uint32_t mask = 0x13579bdfu;
        trie.operate_xor(mask);
        asm volatile("" ::: "memory");
        const auto start = Clock::now();
        std::uint64_t inserted = 0;
        for (std::size_t i = 0; i < operations; ++i) {
            inserted += trie.insert_unique(key(i % distinct) ^ mask, id_for(i, ids));
        }
        elapsed += std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now() - start).count();
        if (inserted != (mode == 1 ? 0 : distinct) || trie.size() != distinct) std::abort();
        checksum += inserted + trie.size();
        for (std::size_t i = 0; i < distinct; ++i) {
            const auto result = trie.find(key(i) ^ mask);
            if (result.first != 1 || result.second.size() != (id_for(i, ids) == -1 ? 0u : 1u)) std::abort();
        }
    }
    sink = checksum;
    const char *kind[] = {"new", "existing", "reuse"};
    const char *id_kind[] = {"anon", "IDs", "mixed"};
    std::printf("D%zu/%s/%s/unique,%.6f,%" PRIu64 "\n", distinct, kind[mode], id_kind[ids],
                static_cast<double>(elapsed) / (operations * rounds), checksum);
}
int main() {
    std::puts("case,ns_per_op,checksum");
    for (std::size_t distinct : {std::size_t{1}, std::size_t{32}, std::size_t{100000}})
        for (int ids : {0, 1, 2})
            for (int mode : {0, 1, 2}) run(distinct, ids, mode);
}

