#define BARRIER() asm volatile("" ::: "memory")
template<int Op,class Trie,class T> __attribute__((noinline)) std::uint64_t query(Trie&tr,const std::vector<T>&q,std::size_t n){std::uint64_t r=0;for(std::size_t i=0;i<n;++i){BARRIER();const T x=q[i&(q.size()-1)];if constexpr(Op==0)r+=tr.find(x).first;else if constexpr(Op==1)r+=tr.count(x);else if constexpr(Op==2)r+=tr.contains(x);else if constexpr(Op==3)r+=static_cast<std::uint64_t>(tr.min_element().first);else if constexpr(Op==4)r+=static_cast<std::uint64_t>(tr.max_element().first);else if constexpr(Op==5)r+=static_cast<std::uint64_t>(tr.min_xor(x).first);else if constexpr(Op==6)r+=static_cast<std::uint64_t>(tr.max_xor(x).first);else if constexpr(Op==7)r+=static_cast<std::uint64_t>(tr.get_kth(1+static_cast<std::uint64_t>(x)%tr.size()).first);else if constexpr(Op==8)r+=tr.count_less(x);else if constexpr(Op==9)r+=tr.count_xor_less(x,q[(i*17+29)&(q.size()-1)]);else if constexpr(Op==10){tr.operate_xor(x);r+=tr.size();}}if constexpr(Op==10){for(std::size_t i=0;i<n;++i)tr.operate_xor(q[i&(q.size()-1)]);}return r;}
template<int Op=0,class A,class T>void allqueries(const std::string&name,A&a,const std::vector<T>&q){static constexpr const char*names[]={"find","count","contains","min","max","min_xor","max_xor","kth","count_less","count_xor_less","lazy"};const std::size_t n=200000;sink=query<Op>(a,q,4096);auto start=Clock::now();auto sum=query<Op>(a,q,n);sink=sum;double elapsed=std::chrono::duration<double,std::nano>(Clock::now()-start).count();std::printf("%s/%s,%.3f,%" PRIu64 ",%zu\n",name.c_str(),names[Op],elapsed/n,sum,n);if constexpr(Op<10)allqueries<Op+1>(name,a,q);}
template<class T,int L>void scenario(const std::string&name,const std::vector<T>&keys,std::uint64_t mask){BinaryTrie<T,L>a;for(T x:keys)a.add(x);std::mt19937_64 rng(9716);std::vector<T>q(4096);for(std::size_t i=0;i<q.size();++i)q[i]=i%2?keys[rng()%keys.size()]:static_cast<T>(rng()&mask);allqueries(name,a,q);}
int main(){std::puts("case,ns_per_op,checksum,ops");scenario<unsigned,29>("D1",{123456},(1u<<30)-1);std::vector<unsigned>small;for(unsigned i=0;i<32;++i)small.push_back(i*12582917u);scenario<unsigned,29>("D32",small,(1u<<30)-1);std::mt19937_64 rng(427);std::vector<unsigned>random;for(int i=0;i<100000;++i)random.push_back(rng()&((1u<<30)-1));scenario<unsigned,29>("D100k",random,(1u<<30)-1);std::vector<unsigned>dense;for(unsigned i=0;i<65536;++i)dense.push_back(i);scenario<unsigned,15>("dense16",dense,65535);std::vector<std::uint64_t>skew{0};for(int i=0;i<64;++i)skew.push_back(std::uint64_t{1}<<i);scenario<std::uint64_t,63>("skew64",skew,~std::uint64_t{0});std::vector<std::int64_t>signedskew{0};for(int i=0;i<63;++i)signedskew.push_back(std::int64_t{1}<<i);scenario<std::int64_t,62>("signed63",signedskew,(std::uint64_t{1}<<63)-1);std::vector<std::uint64_t>prefix;for(int i=0;i<100000;++i)prefix.push_back(0x7123400000000000ull|(rng()&0xfffffull));scenario<std::uint64_t,63>("prefix64",prefix,~std::uint64_t{0});}

