#include <cstdlib>
#include <new>
#include <cstdio>
#include <chrono>
static std::size_t live_allocations = 0;
static void* obtain(std::size_t n) { void *p = std::malloc(n?n:1); if (!p) throw std::bad_alloc(); ++live_allocations; return p; }
void* operator new(std::size_t n) { return obtain(n); }
void* operator new[](std::size_t n) { return obtain(n); }
void operator delete(void *p) noexcept { if (p) --live_allocations; std::free(p); }
void operator delete[](void *p) noexcept { if (p) --live_allocations; std::free(p); }
void operator delete(void *p,std::size_t) noexcept { if (p) --live_allocations; std::free(p); }
void operator delete[](void *p,std::size_t) noexcept { if (p) --live_allocations; std::free(p); }
#include TRIE_SOURCE
using Clock = std::chrono::steady_clock;
int main() {
 std::puts("case,create_ns,destroy_ns,live");
 for(unsigned n : {1u,32u,100000u}) for(unsigned mode=0; mode<4; ++mode) {
  std::chrono::nanoseconds creating{},destroying{};
  unsigned repeat = n==1?1000:n==32?300:4;
  for(unsigned rep=0;rep<repeat;++rep) {
   const auto old_live=live_allocations;
   auto start = Clock::now();
   auto trie = std::make_unique<BinaryTrie<unsigned,29>>();
   for(unsigned i=0;i<n;++i) {unsigned key=(i*2654435761u)&((1u<<30)-1);trie->add(key,mode==0?-1:static_cast<int>(i));}
   if(mode==2) for(unsigned i=0;i<n;++i) {unsigned key=(i*2654435761u)&((1u<<30)-1);trie->del(key);trie->add(key);}
   if(mode==3) for(unsigned i=0;i<n;++i) {unsigned key=(i*2654435761u)&((1u<<30)-1);trie->del(key);}
   auto middle=Clock::now();trie.reset();auto end=Clock::now();
   creating += std::chrono::duration_cast<std::chrono::nanoseconds>(middle-start);
   destroying += std::chrono::duration_cast<std::chrono::nanoseconds>(end-middle);
   if(live_allocations!=old_live){std::fprintf(stderr,"LEAK %zu %zu\n",live_allocations,old_live);return 2;}
  }
  std::printf("D%u/mode%u,%.3f,%.3f,%zu\n",n,mode,double(creating.count())/repeat,double(destroying.count())/repeat,live_allocations);
 }
}

