int main(){using U=std::uint64_t;constexpr U top=U{1}<<63,maximum=std::numeric_limits<U>::max();std::set<U> vals{0,1,maximum,top,top-1};for(int b=1;b<64;++b){U x=U{1}<<b;vals.insert(x);vals.insert(x-1);if(x<maximum)vals.insert(x+1);}std::vector<U>m;BinaryTrie<U,63,20000>t;for(U v:vals){t.add(v);t.add(v,3);t.add(v,3);m.insert(m.end(),3,v);}for(U mask:{U{0},U{1},top-1,top,maximum}){t.operate_xor(mask);for(auto&v:m)v^=mask;std::sort(m.begin(),m.end());assert(t.min_element().first==m.front());assert(t.max_element().first==m.back());for(std::size_t i=0;i<m.size();++i)assert(t.get_kth(static_cast<std::int64_t>(i+1)).first==m[i]);for(U upper:vals){std::size_t expected=0;for(U v:m)expected+=v<upper;assert(t.count_less(upper)==expected);for(U x:{U{0},U{1},top,maximum}){expected=0;U mn=maximum,mx=0;for(U v:m){expected+=(v^x)<upper;mn=std::min(mn,v^x);mx=std::max(mx,v^x);}assert(t.count_xor_less(x,upper)==expected);assert(t.min_xor(x).first==mn);assert(t.max_xor(x).first==mx);}}assert(t.count_less(std::int64_t{-1})==0);assert(t.count_less(std::numeric_limits<std::int64_t>::min())==0);assert(t.count_less(0)==0);for(U v:m){auto r=t.find(v);assert(r.first==3);assert(r.second==std::vector<int>({3,3}));}}
 for(U v:m){assert(t.del(v));}assert(t.empty());}

