#include <cstdlib>
#include <new>
#include <cstdint>
#include <iostream>
#include <vector>
#include <algorithm>
#include <type_traits>
#ifndef TRIE_SOURCE
#define TRIE_SOURCE "/home/reinsirk/Atcoder_Env/DataStructure/Binary_Trie.cpp"
#endif
static std::int64_t fail_after=-1;
static std::uint64_t allocation_attempts=0;
static void* obtain(std::size_t n){if(fail_after>=0){++allocation_attempts;if(fail_after--==0)throw std::bad_alloc();}if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void* operator new(std::size_t n){return obtain(n);} void* operator new[](std::size_t n){return obtain(n);}
void operator delete(void*p)noexcept{std::free(p);} void operator delete[](void*p)noexcept{std::free(p);}
void operator delete(void*p,std::size_t)noexcept{std::free(p);} void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
#include TRIE_SOURCE
static std::uint64_t checks=0,exceptions=0,successes=0;
#define REQUIRE(x)do{++checks;if(!(x)){std::cerr<<"failed "<<__LINE__<<" "<<#x<<'\n';std::abort();}}while(false)
template<class Tr> void extras(){
 if constexpr(requires(Tr t){t.insert_unique(0u,0);}) {
  for(unsigned initial:{0u,1u,31u,2047u,4095u}) for(int budget=0;budget<9;++budget){
   Tr tr;for(unsigned i=0;i<initial;++i)tr.add(i,static_cast<int>(i));
   const auto key=initial+10000;bool threw=false;fail_after=budget;try{REQUIRE(tr.insert_unique(key,11));}catch(const std::bad_alloc&){threw=true;}fail_after=-1;
   if(threw){++exceptions;REQUIRE(tr.size()==initial);REQUIRE(tr.count(key)==0);for(unsigned i=0;i<initial;++i){REQUIRE(tr.count(i)==1);REQUIRE(tr.find(i).second==std::vector<int>{static_cast<int>(i)});}REQUIRE(tr.insert_unique(key,11));}
   REQUIRE(tr.size()==initial+1);REQUIRE(tr.count(key)==1);REQUIRE(tr.find(key).second==std::vector<int>{11});
   fail_after=0;REQUIRE(!tr.insert_unique(key,12));fail_after=-1;REQUIRE(tr.count(key)==1);REQUIRE(tr.find(key).second==std::vector<int>{11});
  }
 }
 if constexpr(requires(Tr t){t.reserve(std::size_t{});}){
  for(int budget=0;budget<9;++budget){Tr tr;for(unsigned i=0;i<32;++i)tr.add(i,static_cast<int>(i));fail_after=budget;try{tr.reserve(10000);}catch(const std::bad_alloc&){++exceptions;}fail_after=-1;REQUIRE(tr.size()==32);for(unsigned i=0;i<32;++i){REQUIRE(tr.count(i)==1);REQUIRE(tr.find(i).second==std::vector<int>{static_cast<int>(i)});}tr.add(10000,9);REQUIRE(tr.count(10000)==1);}
 }
}
int main(){extras<BinaryTrie<std::uint32_t,31,1000000>>();for(std::uint32_t initial:{0u,1u,2u,2040u,2047u,2048u,4095u,4096u})for(std::uint32_t key:{0u,initial+1,0x80000000u})for(int mode=0;mode<3;++mode)for(int budget=0;budget<9;++budget){
 BinaryTrie<std::uint32_t,31,1000000>tr;for(std::uint32_t i=0;i<initial;++i)tr.add(i);if(mode>0){tr.add(key,5);if(mode==2){tr.add(key,6);tr.add(key,7);tr.add(key,8);}}
 const auto oldsize=tr.size();auto oldids=tr.find(key).second;auto oldcount=tr.count(key);bool threw=false;
 fail_after=budget;try{tr.add(key,11);}catch(const std::bad_alloc&){threw=true;}fail_after=-1;
 if(threw){++exceptions;REQUIRE(tr.size()==oldsize);REQUIRE(tr.count(key)==oldcount);REQUIRE(tr.find(key).second==oldids);for(std::uint32_t i=0;i<initial;++i)REQUIRE(tr.count(i)==(i==key?oldcount:1));tr.add(key,11);}
 else ++successes;
 REQUIRE(tr.size()==oldsize+1);REQUIRE(tr.count(key)==oldcount+1);oldids.push_back(11);auto now=tr.find(key).second;std::sort(now.begin(),now.end());std::sort(oldids.begin(),oldids.end());REQUIRE(now==oldids);REQUIRE(tr.del(key,11));REQUIRE(tr.size()==oldsize);
 }
 std::cout<<"{\"checks\":"<<checks<<",\"injected_bad_alloc\":"<<exceptions<<",\"successful_add\":"<<successes<<",\"allocation_attempts\":"<<allocation_attempts<<"}\n";
}

