#include <algorithm>
#include <array>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <map>
#include <memory>
#include <new>
#include <set>
#include <stdexcept>
#include <type_traits>
#include <utility>
#include <vector>
static std::int64_t fail_after=-1;
static std::uint64_t attempts=0, checks=0, capfails=0, allocfails=0, runs=0;
static void* obtain(std::size_t n){if(fail_after>=0){++attempts;if(fail_after--==0)throw std::bad_alloc();}if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void* operator new(std::size_t n){return obtain(n);}void* operator new[](std::size_t n){return obtain(n);}
void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
#include TRIE_SOURCE
#define REQUIRE(x) do{++checks;if(!(x)){std::cerr<<"failed "<<__LINE__<<" "<<#x<<'\n';std::abort();}}while(false)
using U=std::uint32_t;
struct Entry{std::size_t count=0;std::vector<int> ids;};
using Model=std::map<U,Entry>;
static std::size_t nodes_for(const Model&m,U mask,U extra){std::vector<U> keys;for(auto&[v,e]:m)keys.push_back(v^mask);keys.push_back(extra^mask);std::sort(keys.begin(),keys.end());keys.erase(std::unique(keys.begin(),keys.end()),keys.end());std::size_t count=33;for(std::size_t i=1;i<keys.size();++i)count+=std::bit_width(keys[i]^keys[i-1]);return count;}
template<class Tr>void verify(const Tr&t,const Model&m){std::size_t sz=0;std::vector<U>order;for(auto&[x,e]:m){sz+=e.count;order.insert(order.end(),e.count,x);auto r=t.find(x);auto ids=r.second, exp=e.ids;std::sort(ids.begin(),ids.end());std::sort(exp.begin(),exp.end());REQUIRE(r.first==e.count);REQUIRE(ids==exp);REQUIRE(t.count(x)==e.count);REQUIRE(t.contains(x));REQUIRE(t.count_less(x)==order.size()-e.count);}REQUIRE(t.size()==sz);REQUIRE(t.empty()==m.empty());if(!m.empty()){REQUIRE(t.min_element().first==order.front());REQUIRE(t.max_element().first==order.back());for(std::size_t k=0;k<order.size();k+=37)REQUIRE(t.get_kth(static_cast<std::int64_t>(k+1)).first==order[k]);for(U q:{0u,1u,0x80000000u,0xffffffffu}){U mn=0xffffffffu,mx=0;std::size_t less=0;for(auto x:order){mn=std::min(mn,x^q);mx=std::max(mx,x^q);less+=(x^q)<0x80000000u;}REQUIRE(t.min_xor(q).first==mn);REQUIRE(t.max_xor(q).first==mx);REQUIRE(t.count_xor_less(q,0x80000000u)==less);}}}
template<std::size_t N>void scenario(int budget,bool unique,bool ids){++runs;BinaryTrie<U,31,N> t;Model m;constexpr U mask=0x13579bdfu;const std::size_t target=std::min<std::size_t>(N,N>=12287?12288:(N>=8191?8192:4096))-2;U n=0;for(;;){std::size_t nodes=1;for(int j=0;j<32;++j)nodes+=((n+1+(std::uint64_t{1}<<j)-1)>>j);if(nodes>target)break;t.add(n,static_cast<int>(n));m[n]={1,{static_cast<int>(n)}};++n;}REQUIRE(n>0);t.add(0);++m[0].count;t.add(0,777);++m[0].count;m[0].ids.push_back(777);REQUIRE(t.del(n-1,static_cast<int>(n-1)));m.erase(n-1);t.operate_xor(mask);Model shifted;for(auto&[v,e]:m)shifted.emplace(v^mask,std::move(e));m=std::move(shifted);verify(t,m);const U key=0x80000000u^mask;const bool expected_cap=nodes_for(m,mask,key)>N;const int id=ids?123456:-1;bool failed=false;fail_after=budget;try{if(unique)REQUIRE(t.insert_unique(key,id));else t.add(key,id);}catch(const std::bad_alloc&){++allocfails;failed=true;}catch(const std::length_error&){++capfails;failed=true;REQUIRE(expected_cap);}fail_after=-1;if(!failed){REQUIRE(!expected_cap);m[key]={1,ids?std::vector<int>{id}:std::vector<int>{}};}verify(t,m);
// Retry without allocation injection. Any abandoned suffix must remain reusable.
if(failed){bool cap=false;try{if(unique)REQUIRE(t.insert_unique(key,id));else t.add(key,id);}catch(const std::length_error&){cap=true;++capfails;}REQUIRE(cap==expected_cap);if(!cap)m[key]={1,ids?std::vector<int>{id}:std::vector<int>{}};verify(t,m);}
// Boundary fill oracle checks no node was lost after partial acquisition.
for(U v=n-1;v<n+24;++v){const U x=v^mask;bool expected=nodes_for(m,mask,x)>N;bool cap=false;try{t.add(x,static_cast<int>(v));}catch(const std::length_error&){cap=true;++capfails;}REQUIRE(cap==expected);if(!cap){++m[x].count;m[x].ids.push_back(static_cast<int>(v));}}verify(t,m);
// Reuse reclaimed nodes repeatedly, including ID/anonymous preference.
const U reuse=mask;for(int rep=0;rep<30;++rep){t.add(reuse);++m[reuse].count;REQUIRE(t.del(reuse));--m[reuse].count;}verify(t,m);
}
int main(){for(bool unique:{false,true})for(bool ids:{false,true})for(int budget:{-1,0,1,2,3,4,5}){scenario<4095>(budget,unique,ids);scenario<4096>(budget,unique,ids);scenario<4097>(budget,unique,ids);scenario<8191>(budget,unique,ids);scenario<8192>(budget,unique,ids);scenario<8193>(budget,unique,ids);scenario<12287>(budget,unique,ids);scenario<12288>(budget,unique,ids);scenario<12289>(budget,unique,ids);scenario<100000>(budget,unique,ids);}std::cout<<"{\"checks\":"<<checks<<",\"runs\":"<<runs<<",\"capacity_failures\":"<<capfails<<",\"bad_alloc\":"<<allocfails<<",\"allocation_attempts\":"<<attempts<<"}\n";}

