#include <cstdlib>
#include <new>
#include <cstddef>
#include <cstdint>
#include <iostream>
static std::int64_t fail_after=-1;
static std::size_t outstanding=0;
static void *obtain(std::size_t n){if(fail_after>=0&&fail_after--==0)throw std::bad_alloc();if(void*p=std::malloc(n?n:1)){++outstanding;return p;}throw std::bad_alloc();}
void*operator new(std::size_t n){return obtain(n);}void*operator new[](std::size_t n){return obtain(n);}
static void release(void*p)noexcept{if(p){--outstanding;std::free(p);}}
void operator delete(void*p)noexcept{release(p);}void operator delete[](void*p)noexcept{release(p);}void operator delete(void*p,std::size_t)noexcept{release(p);}void operator delete[](void*p,std::size_t)noexcept{release(p);}
#include TRIE_SOURCE
int main(){std::size_t tests=0;
 for(int budget=0;budget<8;++budget){const auto start=outstanding;fail_after=budget;try{BinaryTrie<unsigned,31> t;}catch(const std::bad_alloc&){}fail_after=-1;if(outstanding!=start)std::abort();++tests;}
 for(int budget=0;budget<8;++budget){const auto start=outstanding;fail_after=budget;try{BinaryTrie<unsigned,0,1> t;}catch(const std::bad_alloc&){}fail_after=-1;if(outstanding!=start)std::abort();++tests;}
