#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <type_traits>
#include <vector>
#include TRIE_SOURCE
static std::uint64_t checks=0;
#define REQUIRE(x) do{++checks;if(!(x))std::abort();}while(false)
template<class T,int L>void run(){using U=std::make_unsigned_t<T>;constexpr U high=U{1}<<L;constexpr U mask=[] {if constexpr(L+1==std::numeric_limits<U>::digits)return std::numeric_limits<U>::max();else return (U{1}<<(L+1))-1;}();for(U key:{U{0},U{1},high,mask}){BinaryTrie<T,L>tr;tr.add(static_cast<T>(key));tr.add(static_cast<T>(key));std::vector<int> ids{-5,0,7,7};for(int id:ids)tr.add(static_cast<T>(key),id);for(U lazy:{U{0},U{1},high,mask,mask/3}){tr.operate_xor(static_cast<T>(lazy));key^=lazy;for(int k=1;k<=6;++k){const auto result=tr.get_kth(k);REQUIRE(static_cast<U>(result.first)==key);auto actual=result.second;std::sort(actual.begin(),actual.end());REQUIRE(actual==ids);}}}}
int main(){run<std::uint64_t,47>();run<std::uint64_t,48>();run<std::uint64_t,62>();run<std::int64_t,62>();run<std::uint64_t,63>();std::cout<<"{\"checks\":"<<checks<<"}\n";}
